import React, { useState, useEffect, useRef } from 'react';
import { NavLink, useNavigate, useLocation, Outlet } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import {
    LayoutDashboard, Package, Users, Truck, DollarSign,
    Settings, Menu, X, Bell, Moon, Sun, ChevronLeft,
    ShoppingCart, LogOut, Home, Activity, UserCheck,
    Building2, Percent, Layers, Search, ChevronRight, Megaphone
} from 'lucide-react';
import { useTheme } from '../../context/ThemeContext';
import { useAuth } from '../../context/AuthContext';

const navigation = [
    {
        section: 'DASHBOARD', items: [
            { path: '/admin/dashboard', icon: Home, label: 'Home', end: true },
            { path: '/admin/dashboard/analytics', icon: Activity, label: 'Analytics' },
        ]
    },
    {
        section: 'OPERATIONS', items: [
            { path: '/admin/dashboard/products', icon: Package, label: 'Products' },
            { path: '/admin/dashboard/orders', icon: ShoppingCart, label: 'Orders' },
            { path: '/admin/dashboard/ads', icon: Megaphone, label: 'Marketing' },
        ]
    },
    {
        section: 'PEOPLE', items: [
            { path: '/admin/dashboard/sales-reps', icon: UserCheck, label: 'Sales Team' },
            { path: '/admin/dashboard/dispatch', icon: Truck, label: 'Dispatch' },
        ]
    },
    {
        section: 'FINANCE', items: [
            { path: '/admin/dashboard/commissions', icon: Percent, label: 'Commissions' },
            { path: '/admin/dashboard/payments', icon: DollarSign, label: 'Payments' },
        ]
    },
    {
        section: 'SYSTEM', items: [
            { path: '/admin/dashboard/settings', icon: Settings, label: 'Settings' },
        ]
    },
];

const AdminLayout = () => {
    const [sidebarOpen, setSidebarOpen] = useState(false);
    const [sidebarCollapsed, setSidebarCollapsed] = useState(() => localStorage.getItem('sidebarCollapsed') === 'true');
    const [searchOpen, setSearchOpen] = useState(false);
    const [showNotifications, setShowNotifications] = useState(false);
    const { isDark, toggleTheme } = useTheme();
    const { user, logout } = useAuth();
    const navigate = useNavigate();
    const location = useLocation();
    const notificationRef = useRef(null);

    const notifications = [
        { id: 1, text: 'New order #4521 received', time: '2m ago', unread: true },
        { id: 2, text: 'Low stock alert: Wireless Headphones', time: '15m ago', unread: true },
        { id: 3, text: 'Sales rep Emma Johnson hit target', time: '1h ago', unread: false },
    ];
    const unreadCount = notifications.filter(n => n.unread).length;

    useEffect(() => { setSidebarOpen(false); }, [location.pathname]);
    useEffect(() => { localStorage.setItem('sidebarCollapsed', sidebarCollapsed); }, [sidebarCollapsed]);
    useEffect(() => {
        const handleClick = (e) => { if (notificationRef.current && !notificationRef.current.contains(e.target)) setShowNotifications(false); };
        document.addEventListener('mousedown', handleClick);
        return () => document.removeEventListener('mousedown', handleClick);
    }, []);
    useEffect(() => {
        const handleKey = (e) => {
            if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); setSearchOpen(true); }
            if (e.key === 'Escape') { setSearchOpen(false); setShowNotifications(false); }
        };
        document.addEventListener('keydown', handleKey);
        return () => document.removeEventListener('keydown', handleKey);
    }, []);

    const handleLogout = () => { logout(); navigate('/login'); };

    const getPageTitle = () => {
        for (const section of navigation) {
            for (const item of section.items) {
                if (location.pathname === item.path || (item.end && location.pathname === '/admin/dashboard')) return item.label;
            }
        }
        return 'Dashboard';
    };

    return (
        <div className="flex h-screen overflow-hidden bg-surface-light dark:bg-surface-dark">
            {/* Mobile Overlay */}
            {sidebarOpen && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40 lg:hidden" onClick={() => setSidebarOpen(false)} />
            )}

            {/* Sidebar - Fixed on mobile, Static on desktop */}
            <aside className={`fixed lg:relative z-50 h-full bg-white dark:bg-brand-950 border-r border-slate-200 dark:border-brand-800 shadow-2xl transition-all duration-300 flex flex-col flex-shrink-0
        ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'} lg:translate-x-0
        ${sidebarCollapsed ? 'w-[88px]' : 'w-72'}`}>

                {/* Logo */}
                <div className="flex items-center justify-between p-4 border-b border-slate-200 dark:border-brand-800 h-16">
                    <div className="flex items-center gap-3 overflow-hidden">
                        <div className="h-10 w-10 rounded-xl bg-gradient-to-br from-gold-400 via-gold-500 to-gold-600 flex items-center justify-center flex-shrink-0 shadow-lg shadow-gold-500/30">
                            <Layers className="h-5 w-5 text-white" />
                        </div>
                        {!sidebarCollapsed && (
                            <div className="whitespace-nowrap">
                                <h1 className="font-extrabold text-brand-800 dark:text-white text-lg leading-tight">SalesPro</h1>
                                <p className="text-[10px] text-gold-600 dark:text-gold-400 uppercase tracking-[0.2em] font-bold">Enterprise</p>
                            </div>
                        )}
                    </div>
                    <button onClick={() => setSidebarCollapsed(!sidebarCollapsed)} className="hidden lg:flex p-1.5 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-lg flex-shrink-0">
                        <ChevronLeft className={`h-4 w-4 text-slate-500 transition-transform ${sidebarCollapsed ? 'rotate-180' : ''}`} />
                    </button>
                    <button onClick={() => setSidebarOpen(false)} className="lg:hidden p-1.5 flex-shrink-0"><X className="h-5 w-5 text-slate-500" /></button>
                </div>

                {/* Nav */}
                <nav className="flex-1 overflow-y-auto py-3 px-3 space-y-4">
                    {navigation.map((section) => (
                        <div key={section.section}>
                            {!sidebarCollapsed && <p className="px-3 mb-1 text-[10px] font-bold text-slate-400 uppercase tracking-[0.15em]">{section.section}</p>}
                            <div className="space-y-0.5">
                                {section.items.map((item) => (
                                    <NavLink key={item.path} to={item.path} end={item.end} onClick={() => setSidebarOpen(false)}
                                        className={({ isActive }) => `flex items-center gap-3 px-3 py-2.5 rounded-xl transition-all text-sm font-medium ${isActive ? 'bg-brand-50 dark:bg-brand-800/40 text-brand-700 dark:text-gold-400' : 'text-slate-600 dark:text-slate-400 hover:bg-slate-50 dark:hover:bg-brand-800/30'} ${sidebarCollapsed ? 'justify-center' : ''}`}>
                                        <item.icon className="h-5 w-5 flex-shrink-0" />
                                        {!sidebarCollapsed && <span className="whitespace-nowrap">{item.label}</span>}
                                    </NavLink>
                                ))}
                            </div>
                        </div>
                    ))}
                </nav>

                {/* User */}
                <div className="p-3 border-t border-slate-200 dark:border-brand-800">
                    <div className="flex items-center gap-3">
                        <div className="h-9 w-9 rounded-xl bg-gradient-to-br from-brand-600 to-brand-800 flex items-center justify-center flex-shrink-0 shadow-md">
                            <span className="text-white text-sm font-bold">{user?.firstName?.[0]}{user?.lastName?.[0]}</span>
                        </div>
                        {!sidebarCollapsed && (
                            <div className="flex-1 min-w-0">
                                <p className="text-sm font-semibold text-brand-800 dark:text-white truncate">{user?.firstName} {user?.lastName}</p>
                                <p className="text-xs text-slate-500 truncate capitalize">{user?.role?.replace(/_/g, ' ')}</p>
                            </div>
                        )}
                        {!sidebarCollapsed && (
                            <button onClick={handleLogout} className="p-1.5 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-lg flex-shrink-0">
                                <LogOut className="h-4 w-4 text-slate-400 hover:text-rose-500" />
                            </button>
                        )}
                    </div>
                </div>
            </aside>

            {/* Main Content */}
            <div className="flex-1 flex flex-col min-w-0 overflow-y-auto">
                {/* Top Bar */}
                <header className="sticky top-0 z-30 bg-white/80 dark:bg-brand-950/80 backdrop-blur-xl border-b border-slate-200 dark:border-brand-800 flex-shrink-0">
                    <div className="flex items-center justify-between px-4 lg:px-6 h-16">
                        <div className="flex items-center gap-3">
                            <button onClick={() => setSidebarOpen(true)} className="lg:hidden p-2 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-xl">
                                <Menu className="h-5 w-5 text-slate-600 dark:text-slate-400" />
                            </button>
                            <h2 className="text-lg font-bold text-brand-800 dark:text-white">{getPageTitle()}</h2>
                        </div>
                        <div className="flex items-center gap-2">
                            <div className="relative" ref={notificationRef}>
                                <button onClick={() => setShowNotifications(!showNotifications)} className="relative p-2 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-xl">
                                    <Bell className="h-5 w-5 text-slate-500 dark:text-slate-400" />
                                    {unreadCount > 0 && <span className="absolute top-1 right-1 h-5 w-5 bg-rose-500 text-white text-[10px] font-bold rounded-full flex items-center justify-center">{unreadCount}</span>}
                                </button>
                                {showNotifications && (
                                    <div className="absolute right-0 mt-2 w-80 bg-white dark:bg-brand-900 rounded-2xl shadow-2xl border border-slate-200 dark:border-brand-700 overflow-hidden z-50">
                                        <div className="p-4 border-b"><h3 className="font-semibold">Notifications</h3></div>
                                        <div className="max-h-80 overflow-y-auto">
                                            {notifications.map(n => (
                                                <div key={n.id} className="p-4 hover:bg-slate-50 dark:hover:bg-brand-800/50 cursor-pointer">
                                                    <p className="text-sm">{n.text}</p><p className="text-xs text-slate-500 mt-1">{n.time}</p>
                                                </div>
                                            ))}
                                        </div>
                                    </div>
                                )}
                            </div>
                            <button onClick={toggleTheme} className="p-2 hover:bg-slate-100 dark:hover:bg-brand-800 rounded-xl">
                                {isDark ? <Sun className="h-5 w-5 text-gold-500" /> : <Moon className="h-5 w-5 text-brand-600" />}
                            </button>
                        </div>
                    </div>
                </header>

                {/* Page Content */}
                <main className="flex-1 p-4 lg:p-6 overflow-y-auto">
                    <Outlet />
                </main>
            </div>
        </div>
    );
};

export default AdminLayout;
